using EddaStore.Models.Customers; using EddaStore.Repositories.Interfaces; using EddaStore.Services.Interfaces;
namespace EddaStore.Services;
public class ReviewAdminService(IGenericRepository<Review> repository):IReviewAdminService { public Task<IReadOnlyList<Review>> GetAllAsync(CancellationToken ct=default)=>repository.GetAllAsync(ct); public async Task SetApprovalAsync(Guid id,bool approved,CancellationToken ct=default){var x=await repository.GetByIdAsync(id,ct)??throw new KeyNotFoundException();x.IsApproved=approved;repository.Update(x);await repository.SaveChangesAsync(ct);}public async Task DeleteAsync(Guid id,CancellationToken ct=default){var x=await repository.GetByIdAsync(id,ct)??throw new KeyNotFoundException();repository.Delete(x);await repository.SaveChangesAsync(ct);}}
